import React from 'react'
import PropTypes from 'prop-types'
import {Box, Image} from '@salesforce/retail-react-app/app/components/shared/ui'

/**
 * Simple ImageTile component that displays a responsive image.
 * This component can be placed inside any Layout component.
 */
export const ImageTile = ({image}) => {
  return (
    <Box className="image-tile">
      <figure>
        <picture>
          <source srcSet={image?.src?.tablet} media="(min-width: 48em)" />
          <source srcSet={image?.src?.desktop} media="(min-width: 64em)" />
          <Image src={image?.src?.mobile || image?.url} alt={image?.alt} title={image?.alt} />
        </picture>
      </figure>
    </Box>
  )
}

ImageTile.propTypes = {
  image: PropTypes.shape({
    url: PropTypes.string,
    alt: PropTypes.string,
    src: PropTypes.shape({
      mobile: PropTypes.string,
      tablet: PropTypes.string,
      desktop: PropTypes.string
    })
  })
}

export default ImageTile
```

### Locale Only in Query Params

```typescript
// config.server.ts
export default defineConfig({
  app: {
    url: {
      search: "?lng=:localeId",
      excludeRoutes: ["/resource/**", "/action/**"],
    },
    // No detection config override required.
    // Path detection doesn't find valid site/locale IDs in page path segments
    // and falls through. Site resolves from cookie or header; locale from ?lng=.
  },
});
```

No detection config override is required. The default detection falls through path segments to find the locale in the `?lng=` query parameter.

Best for: Single-site storefronts that want locale-aware URLs without path changes.

| Page     | URL                          |
| -------- | ---------------------------- |
| Homepage | `/?lng=en-GB`                |
| Product  | `/product/123?lng=en-GB`     |
| Category | `/category/womens?lng=it-IT` |

